', 'to_nodes = [trans.to_node] if isinstance(trans.to_node, str) else [tn if isinstance(tn, str) else tn.to_node for tn in trans.to_node]', 'to_nodes = [trans.to_node] if isinstance(trans.to_node, str) else [tn if isinstance(tn, str) else tn.to_node for tn in trans.to_node]', 'namespaced_to_nodes = [f"{parent_name}/{to_node}" for to_node in to_nodes]', 'if __name__ == "__main__":', 'inputs_mapping={"text": "lambda ctx: ctx['farewell'] if ctx['result'] == 'no' else ctx['ai_result']"}', 'namespaced_to_nodes = [f"{parent_name}/{to_node}" for to_node in to_nodes]', 'while to_visit:
